int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int ret = 0;
    unsigned int id = reg->id;
    void *val = (void *)(long)reg->addr;
    int offset = kvm_register_offset(id);
    int size = kvm_register_size(id);

    if (offset < 0 || size <= 0) {
        ret = -ENOENT;
        goto out;
    }

    if ((unsigned long)val + size > current->mm->task_size) {
        ret = -EFAULT;
        goto out;
    }

    if (copy_from_user(vcpu->run->kvm_run_data + offset, val, size)) {
        ret = -EFAULT;
        goto out;
    }

    if (id == KVM_REG_ARM_CORE_PSTATE) {
        u64 pstate;
        copy_from_user(&pstate, val, sizeof(pstate));
        if (pstate & ~(ARM_CORE_PSTATE_MASK)) {
            ret = -EINVAL;
            goto out;
        }
        vcpu->arch.pstate = pstate;
    }

    vcpu->arch.regs[offset / sizeof(u64)] = *(u64 *)((u8 *)vcpu->arch.regs + offset);

out:
    return ret;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int ret = 0;
    void *val = (void *)(long)reg->addr;
    unsigned int id = reg->id & KVM_REG_MASK;
    int offset = kvm_reg_offset(id);

    if (offset < 0)
        return -ENOENT;

    if (!kvm_reg_size(id) || kvm_reg_size(id) > sizeof(long))
        return -EINVAL;

    if (copy_from_user(&vcpu->tmp, val, sizeof(vcpu->tmp)))
        return -EFAULT;

    if (id == KVM_REG_X86_PSR) {
        if ((vcpu->tmp & KVM_PSR_MODE_MASK) != KVM_PSR_MODE_LEGACY) {
            if (kvm_check_cap(KVM_CAP_PV_EOI) && vcpu->tmp & KVM_PSR_PV_EOI)
                vcpu->pv_eoi_enabled = true;
            else
                ret = -EINVAL;
        }
    }

    switch (id) {
        case KVM_REG_X86_PSR:
            vcpu->arch.regs[VCPU_REGS_PSR] = vcpu->tmp;
            break;
        default:
            if (offset >= 0 && offset < sizeof(vcpu->arch.regs))
                *(unsigned long *)((void *)(&vcpu->arch.regs) + offset) = vcpu->tmp;
            else
                ret = -ENOENT;
    }

    return ret;
}

int kvm_set_one_core_reg(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int ret = 0;
    void *kaddr;
    unsigned int offset;

    switch (reg->id) {
    case KVM_REG_ARM_CORE_REG(0 ... N):
        offset = calculate_offset(reg->id);
        if (offset == 0)
            return -ENOENT;
        break;
    default:
        return -ENOENT;
    }

    if (offset >= sizeof(vcpu->arch.core_reg))
        return -EINVAL;

    kaddr = (void *)&vcpu->arch.core_reg + offset;
    if (copy_from_user(kaddr, (void __user *)(unsigned long)reg->addr, reg->bytes))
        return -EFAULT;

    if (reg->id == KVM_REG_ARM_CORE_PSTATE) {
        unsigned long pstate = *(unsigned long *)kaddr;
        if (pstate & ~(KVM_PSTATE_MASK))
            return -EINVAL;
        if ((pstate & PSR_MODE_MASK) != PSR_MODE_EL1)
            return -EPERM;
    }

    return ret;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int r = 0;
    void *val;

    if (reg->id < KVM_REG_CORE || reg->id >= KVM_REG_CORE_NEXT)
        return -ENOENT;

    val = memdup_user((const void __user *)(unsigned long)reg->addr, sizeof(long));
    if (IS_ERR(val))
        return PTR_ERR(val);

    if (reg->id == KVM_REG_PSR) {
        unsigned long psr = *(unsigned long *)val;

        if (psr & KVM_PSR_RESERVED_MASK) {
            r = -EINVAL;
            goto out;
        }

        if ((psr & KVM_PSR_MODE_MASK) != vcpu->mode) {
            r = -EINVAL;
            goto out;
        }
    }

    switch (reg->id) {
        case KVM_REG_PSR:
            vcpu->guest_regs.psr = *(unsigned long *)val;
            break;
        case KVM_REG_IP:
            vcpu->guest_regs.rip = *(unsigned long *)val;
            break;
        case KVM_REG_SP:
            vcpu->guest_regs.rsp = *(unsigned long *)val;
            break;
        default:
            r = -ENOENT;
            goto out;
    }

out:
    kfree(val);
    return r;
}

int kvm_set_one_core_register(struct kvm_vcpu *vcpu, const struct kvm_one_reg *reg)
{
    int offset;
    int ret = 0;
    void *val;

    offset = kvm_get_register_offset(reg->id);
    if (offset < 0)
        return -ENOENT;

    val = (char *)vcpu + offset;
    if (copy_from_user(val, (void __user *)reg->addr, reg->size)) {
        return -EFAULT;
    }

    if (reg->id == KVM_REG_ARM_PSTATE) {
        unsigned long pstate = *(unsigned long *)val;

        if (pstate & ~KVM_PSTATE_MASK)
            return -EINVAL;

        if ((pstate & KVM_PSTATE_MODE_MASK) != KVM_PSTATE_MODE_EL1 &&
            (pstate & KVM_PSTATE_MODE_MASK) != KVM_PSTATE_MODE_EL2 &&
            (pstate & KVM_PSTATE_MODE_MASK) != KVM_PSTATE_MODE_EL3)
            return -EINVAL;
    }

    return ret;
}
